def apply_visual_design():
    """Apply the requested decorative theme while keeping native accessible UI controls."""
    # The user explicitly requested textures and shadows; static CSS contains no app data.
    st.html(config.THEME_CSS_FILE)
    # Numeric geometry shares one source of truth with the time-axis calculations.
    st.html('<style>:root{'
            f'--ww-hour-height:{config.CALENDAR_HOUR_HEIGHT}px;'
            f'--ww-track-height:{config.CALENDAR_TRACK_HEIGHT}px;'
            '}</style>')
    st.logo(str(config.APP_WORDMARK_FILE), size='large', icon_image=str(config.APP_ICON_FILE))


def render_chart(figure, alt):
    """Match a detached chart to Navy & Oak without changing data or global plot settings."""
    palette = config.CHART_THEME
    figure.set_facecolor(palette['background'])
    for axis in figure.axes:
        axis.set_facecolor(palette['background'])
        axis.tick_params(colors=palette['muted'])
        for text in [axis.title, axis.xaxis.label, axis.yaxis.label, *axis.texts]:
            text.set_color(palette['text'])
        for spine in axis.spines.values():
            spine.set_color(palette['border'])
        legend = axis.get_legend()
        if legend is not None:
            legend.get_frame().set_facecolor(palette['surface'])
            legend.get_frame().set_edgecolor(palette['border'])
            for text in legend.get_texts():
                text.set_color(palette['text'])
    st.pyplot(figure, alt=alt)


# Course: L04 – resource caching reuses the connection across Streamlit reruns.
# Clearing this cache creates a new connection; the local app performs transactional writes.
@st.cache_resource
def cached_connection():
    """Return the shared local SQLite connection."""
    return database.get_connection()


# New ratings change the count; edits change the revision. Ordinary reruns reuse the same model.
@st.cache_resource(max_entries=config.ML_MODEL_CACHE_ENTRIES, show_spinner=False)
def cached_recommender(n_ratings, ratings_revision=0):
    """Train once per effective rating change and keep at most two models in memory."""
    X, y, weights = recommender.build_training_data(cached_connection())
    model = recommender.train_production_model(X, y, weights)
    return recommender.Recommender(model, list(X.columns))


# Count plus revision detects new/edited ratings; refresh/reset explicitly clear feature changes.
@st.cache_data(ttl=config.ML_EVALUATION_CACHE_SECONDS, max_entries=config.ML_MODEL_CACHE_ENTRIES,
               show_spinner=False)
def cached_evaluation(n_ratings, ratings_revision=0):
    """Evaluate on demand, retaining only two in-memory comparison reports for one hour."""
    X, y, _ = recommender.build_training_data(cached_connection())
    return recommender.evaluate_models(X, y)


def clear_data_caches():
    """Discard public-data, calendar and model caches after explicit refresh or reset."""
    for cached in (cached_events, cached_calendar, cached_api_available,
                   cached_recommender, cached_evaluation):
        cached.clear()


def render_reset_controls(connection):
    """Reset local database and session state only after the user's confirmation checkbox."""
    st.subheader('Reset demo data')
    st.caption('Removes your profile, favorites, plans and ratings, then rebuilds the demo. '
               'Remembered calendar and source files are kept.')
    confirmed = st.checkbox('I want to reset all WeekWise data', key='ww_reset_confirm')
    if st.button('Reset demo data', disabled=not confirmed, key='ww_reset_data'):
        database.reset_database(connection)
        connection.close()
        clear_data_caches()
        cached_connection.clear()
        st.session_state.clear()
        st.rerun()


# Private calendar values are cached in memory only, never persisted to disk by Streamlit.
# Mode, range, input, privacy setting, recognized IDs and file revision all invalidate this cache.
@st.cache_data(ttl=config.CALENDAR_CACHE_SECONDS, max_entries=config.CALENDAR_CACHE_ENTRIES,
               show_spinner=False)
def cached_calendar(mode, start, end, link=None, upload_bytes=None, all_day_busy=False,
                    known_event_ids=(), file_revision=()):
    """Cache parsed calendar results briefly to avoid repeated downloads on ordinary reruns."""
    return calendar_import.load_calendar(mode, start, end, link, upload_bytes,
                                         all_day_busy=all_day_busy,
                                         known_event_ids=known_event_ids)


def calendar_file_revision():
    """Return file metadata so remembered inputs and regenerated demos invalidate the cache."""
    versions = []
    for path in (config.DEMO_CALENDAR_FILE, config.PRIVATE_CALENDAR_LINK_FILE,
                 config.PRIVATE_CALENDAR_UPLOAD_FILE):
        versions.append(path.stat().st_mtime_ns if path.exists() else None)
    return tuple(versions)


# Health expires after 30 seconds; failed operations additionally suppress probes for that period.
@st.cache_data(ttl=config.API_HEALTH_CACHE_SECONDS, max_entries=1, show_spinner=False)
def cached_api_available():
    """Probe the optional local API without delaying every widget rerun."""
    return api_client.is_api_available()


def api_available(now=None):
    """Respect a recent operation failure even while the health cache still says available."""
    now = config.local_now(now)
    failed = st.session_state.get('ww_api_failed_at')
    if failed is not None:
        if now - failed < timedelta(seconds=config.API_HEALTH_CACHE_SECONDS):
            return False
        st.session_state.pop('ww_api_failed_at', None)
        cached_api_available.clear()
    return cached_api_available()


def _record_api_origin(origin, attempted_api):
    """Record actual fallback immediately so a write-triggered rerun does not retry a dead API."""
    st.session_state['ww_event_data_origin'] = origin
    if attempted_api and origin == 'database':
        st.session_state['ww_api_failed_at'] = config.local_now()
        cached_events.clear()


# Source refreshes/failures clear this cache; availability changes its key; otherwise TTL is 60 s.
@st.cache_data(ttl=config.EVENT_CACHE_SECONDS, max_entries=config.EVENT_CACHE_ENTRIES,
               show_spinner=False)
def cached_events(start, end, available=True):
    """Cache event objects together with their origin, without hiding a database fallback."""
    return api_client.get_events(start, end, available, cached_connection())


def load_events(start, end):
    """Load the week and reflect any API failure outside the cached function's body."""
    available = api_available()
    events, origin = cached_events(start, end, available)
    _record_api_origin(origin, available)
    return events


def load_event(event_id):
    """Read current details through the API or the identical local representation."""
    available = api_available()
    event, origin = api_client.get_event(event_id, available, cached_connection())
    _record_api_origin(origin, available)
    return event


def save_user_interaction(user_id, event_id, action, rating=None, now=None):
    """Route every UI attendance/planning write through the API client and record its origin."""
    available = api_available()
    result, origin = api_client.save_interaction(user_id, event_id, action, rating, available,
                                                cached_connection(), now)
    _record_api_origin(origin, available)
    return result


def direction_badge(direction_key, label=None):
    """Show direction text as well as its shared accessible Streamlit color."""
    st.badge(label or config.DIRECTION_LABELS[direction_key],
             color=categories.direction_color(direction_key))


def render_sidebar_status(used_mode=None):
    """Show the current profile, actual calendar origin and clearly labelled demo data."""
    connection = cached_connection()
    user_id = database.get_current_user_id(connection)
    used_mode = used_mode or st.session_state.get('ww_used_calendar_mode', 'demo')
    with st.sidebar:
        if user_id is not None:
            st.text(database.get_user_profile(connection, user_id).display_name)
        origin = 'api' if api_available() else 'database'
        st.caption(config.API_STATUS_LABELS[origin])
        st.caption('Calendar: ' + config.CALENDAR_MODES.get(used_mode, 'Unavailable'))
        demo = database.get_demo_counts(connection)
        if demo['placeholder_series'] or demo['synthetic_users']:
            st.badge('Demo data', color='gray')
            st.caption(f'{demo["placeholder_series"]} placeholder activity series · '
                       f'{demo["synthetic_users"]} synthetic users.')


def initialize_calendar_state(connection):
    """Restore only non-secret switches and the selected source, retaining session-only inputs."""
    defaults = {'ww_calendar_mode': database.get_setting(connection, 'calendar_mode', 'demo'),
                'ww_calendar_link': None, 'ww_calendar_upload': None,
                'ww_hide_busy_titles': database.get_setting(
                    connection, 'hide_busy_titles', '0') == '1',
                'ww_all_day_busy': database.get_setting(connection, 'all_day_busy', '0') == '1'}
    for key, value in defaults.items():
        if key not in st.session_state:
            st.session_state[key] = value


def load_current_calendar(connection, start, end, known_ids=()):
    """Read the selected source and record the actual origin for sidebar status."""
    initialize_calendar_state(connection)
    result = cached_calendar(st.session_state['ww_calendar_mode'], start, end,
                             st.session_state['ww_calendar_link'],
                             st.session_state['ww_calendar_upload'],
                             st.session_state['ww_all_day_busy'], tuple(sorted(known_ids)),
                             calendar_file_revision())
    st.session_state['ww_used_calendar_mode'] = result[3]
    return result


def calendar_source_inputs():
    """Render shared source, masked-link, upload and explicit Remember widgets."""
    choices = list(config.CALENDAR_MODES)
    mode = st.radio('Calendar source', choices, format_func=config.CALENDAR_MODES.get,
                    index=choices.index(st.session_state.get('ww_calendar_mode', 'demo')),
                    key='ww_calendar_choice')
    link, upload = None, None
    if mode == 'link':
        link = st.text_input('Secret iCal link', type='password',
                             value=st.session_state.get('ww_calendar_link') or '',
                             key='ww_calendar_link_input')
        with st.expander('Find your calendar link'):
            st.write('Google: Calendar settings → Secret address in iCal format.')
            st.write('Outlook: Shared calendars → Publish a calendar → ICS link. '
                     'If publishing is disabled, upload an exported .ics file.')
    elif mode == 'upload':
        file = st.file_uploader('Upload an .ics file', type=['ics'], key='ww_calendar_upload_input')
        if file is not None:
            upload = file.getvalue()
        else:
            upload = st.session_state.get('ww_calendar_upload')
            if upload is not None:
                st.caption('Using the file from this session. Upload another to replace it.')
    remember = False
    if mode != 'demo':
        remember = st.checkbox('Remember on this computer', key='ww_remember_calendar')
        st.caption('Without Remember, your calendar input stays only in this session.')
    return mode, link or None, upload, remember


def test_calendar_input(mode, link, upload, now=None):
    """Test two weeks of input without storing private content or exposing raw errors."""
    start = config.local_now(now)
    result = calendar_import.load_calendar(mode, start,
                                           start + timedelta(days=config.CALENDAR_TEST_DAYS),
                                           link, upload)
    blocks, labels, recognized, used_mode, message = result
    # With no known-ID suppression, every recognized timed occurrence is already in blocks.
    count = len(blocks) + sum(len(values) for values in labels.values())
    return {'input': (mode, link, upload), 'ok': used_mode == mode,
            'count': count, 'message': message, 'used_mode': used_mode}


def show_calendar_test(result):
    """Display a bounded test result without rendering input bytes, private titles or links."""
    if result['ok']:
        st.success(f"Found {result['count']} entries in the next {config.CALENDAR_TEST_DAYS} days.")
    else:
        st.warning(result['message'])


def apply_calendar(connection, mode, link, upload, remember, start, end):
    """Apply a source, allowing a visible safe fallback and persisting only explicit opt-ins."""
    result = calendar_import.load_calendar(mode, start, end, link, upload)
    has_new_input = (mode == 'link' and link is not None) or (
        mode == 'upload' and upload is not None)
    if remember and has_new_input and result[3] == mode:
        calendar_import.remember_calendar(mode, link, upload)
    st.session_state['ww_calendar_mode'] = mode
    st.session_state['ww_calendar_link'] = link
    st.session_state['ww_calendar_upload'] = upload
    cached_calendar.clear()
    database.set_setting(connection, 'calendar_mode', mode)
    st.rerun()


def _forget_calendar(connection):
    """Forget stored inputs and reset widgets without touching public data or confirmations."""
    calendar_import.forget_calendar()
    st.session_state['ww_calendar_link'] = None
    st.session_state['ww_calendar_upload'] = None
    st.session_state['ww_calendar_mode'] = 'demo'
    for key in ('ww_calendar_choice', 'ww_calendar_link_input', 'ww_calendar_upload_input',
                'ww_remember_calendar', 'ww_calendar_test'):
        if key in st.session_state:
            del st.session_state[key]
    cached_calendar.clear()
    database.set_setting(connection, 'calendar_mode', 'demo')
    st.rerun()


def render_calendar_controls(connection, start, end):
    """Show Calendar settings, source testing and privacy options in the current container."""
    initialize_calendar_state(connection)
    mode, link, upload, remember = calendar_source_inputs()
    if mode == 'link' and st.button('Test link', key='ww_test_calendar'):
        st.session_state['ww_calendar_test'] = test_calendar_input(mode, link, upload)
    result = st.session_state.get('ww_calendar_test')
    if result and result['input'] == (mode, link, upload):
        show_calendar_test(result)
    if st.button('Use calendar', key='ww_apply_calendar'):
        apply_calendar(connection, mode, link, upload, remember, start, end)
    st.checkbox('Treat all-day entries as busy', key='ww_all_day_busy')
    st.checkbox('Hide titles of my calendar entries', key='ww_hide_busy_titles')
    _save_privacy_settings(connection)
    if st.button('Forget remembered calendar', key='ww_forget_calendar'):
        _forget_calendar(connection)
    current = load_current_calendar(connection, start, end)
    if current[4]:
        st.warning(current[4])


def _save_privacy_settings(connection):
    """Persist only non-secret switches, rerunning after each changed database setting."""
    for setting, key in (('all_day_busy', 'ww_all_day_busy'),
                         ('hide_busy_titles', 'ww_hide_busy_titles')):
        value = '1' if st.session_state[key] else '0'
        if database.get_setting(connection, setting, '0') != value:
            database.set_setting(connection, setting, value)
            st.rerun()


def render_profile_fields(name, directions, key_prefix):
    """Render the shared name and three colored focus choices, returning unsaved input."""
    name = st.text_input('Display name', value=name, max_chars=config.DISPLAY_NAME_MAX,
                         key=key_prefix + '_name')
    selected = set()
    for key, label in config.DIRECTION_LABELS.items():
        color = categories.direction_color(key)
        if st.checkbox(f':{color}[{label}]', value=key in directions,
                        key=key_prefix + '_' + key):
            selected.add(key)
        st.caption(config.DIRECTION_EXAMPLES[key])
    return name, selected


def _clear_filters():
    """Reset saved filter choices and their widget values before the next rerun."""
    st.session_state['ww_filters'] = {'favorites': False, 'bundles': set()}
    for key in list(st.session_state):
        if key.startswith('ww_filter_bundle_') or key == 'ww_filter_favorites':
            st.session_state[key] = False
        elif key.startswith('ww_filter_many_'):
            st.session_state[key] = []


def render_filters(connection):
    """Read favorites OR bundle filters, choosing compact controls for larger directions."""
    previous = st.session_state.get('ww_filters', {'favorites': False, 'bundles': set()})
    selected = set()
    frame = database.get_categories_df(connection)
    with st.sidebar:
        st.subheader('Filters')
        favorites = st.checkbox('Favorites', value=previous['favorites'],
                                 key='ww_filter_favorites')
        for direction, label in config.DIRECTION_LABELS.items():
            rows = frame[frame['direction_key'] == direction]
            names = dict(zip(rows['bundle_key'], rows['bundle_name']))
            color = categories.direction_color(direction)
            with st.expander(f':{color}[{label}]'):
                if len(names) > config.FILTER_LIST_MAX:
                    defaults = [key for key in names if key in previous['bundles']]
                    widget_key = 'ww_filter_many_' + direction
                    if widget_key not in st.session_state:
                        st.session_state[widget_key] = defaults
                    selected.update(st.multiselect(label, list(names), format_func=names.get,
                                                    key=widget_key))
                else:
                    for key, name in names.items():
                        if st.checkbox(name, value=key in previous['bundles'],
                                        key='ww_filter_bundle_' + key):
                            selected.add(key)
        st.button('Clear filters', on_click=_clear_filters, key='ww_clear_filters')
        st.caption('Matches use activity details, your focus, favorites, ratings '
                   'and friends going.')
    filters = {'favorites': favorites, 'bundles': selected}
    st.session_state['ww_filters'] = filters
    return filters


def _public_links(event):
    """Show safe HTTP(S) registration and original-page links for the public event."""
    for label, url in (('Register', event.registration_url), ('Original page', event.source_url)):
        if url:
            parsed = urlsplit(url)
            if parsed.scheme in ('http', 'https') and parsed.hostname:
                st.link_button(label, url)


def render_event_card(suggestion, key_prefix, show_link=False):
    """Display a scored candidate and queue its details without opening a dialog in the loop."""
    event = suggestion.event
    direction_badge(event.direction_key)
    st.caption(event.bundle_name)
    title = event.title
    if len(title) > config.EVENT_TITLE_MAX_CHARS:
        title = title[:config.EVENT_TITLE_MAX_CHARS] + '…'
    st.markdown(f'**{title}**')
    st.caption(f'{event.start:%H:%M}–{event.end:%H:%M} · {event.source_label()}')
    if event.display_tags():
        st.caption(' · '.join(event.display_tags()))
    st.caption(suggestion.match_label())
    if suggestion.reasons:
        st.caption(' · '.join(suggestion.reasons))
    if suggestion.friends_going:
        st.badge(f'{suggestion.friends_going} friends going', color='green')
    if suggestion.is_invited():
        st.badge(suggestion.invited_by + ' invited you', color=config.INVITATION_BADGE_COLOR)
    if st.button('Details', key=f'{key_prefix}_details_{event.event_id}'):
        st.session_state['ww_open_event_id'] = event.event_id
    if show_link:
        _public_links(event)


def _selected_more(key):
    """Queue one dropdown selection and reset it so dismissing the dialog stays dismissed."""
    selected = st.session_state[key]
    if selected is not None:
        st.session_state['ww_open_event_id'] = selected
        st.session_state[key] = None


def _more_label(event_id, choices):
    """Format a remaining suggestion without changing its stored ID."""
    if event_id is None:
        return 'Choose another activity'
    suggestion = choices[event_id]
    return f'{suggestion.event.start:%H:%M} · {suggestion.event.title} · {suggestion.score:.0%}'


def render_gap_suggestions(suggestions, gap, profile, filters, column_layout=False):
    """Show top three plus dropdown, or every filtered match up to the stated display cap."""
    filtered = recommender.filter_suggestions(suggestions, profile, filters['bundles'],
                                              filters['favorites'])
    active = filters['favorites'] or bool(filters['bundles'])
    limit = config.MAX_EVENTS_PER_GAP_FILTER_VIEW if active else config.TOP_SUGGESTIONS_PER_GAP
    if not filtered:
        message = 'No matching activities in this gap.' if active else 'No activities in this gap.'
        st.caption(message)
    visible = filtered[:limit]
    columns = []
    if column_layout and visible:
        columns = st.columns(min(config.TOP_SUGGESTIONS_PER_GAP, len(visible)))
    for index, suggestion in enumerate(visible):
        if column_layout:
            with columns[index % len(columns)]:
                render_event_card(suggestion, 'ww_gap_' + gap.gap_id, show_link=active)
        else:
            render_event_card(suggestion, 'ww_gap_' + gap.gap_id, show_link=active)
    if active and len(filtered) > limit:
        st.caption(f'+ {len(filtered) - limit} more – narrow your filter')
    elif not active and len(filtered) > limit:
        choices = {}
        for suggestion in filtered[limit:]:
            choices[suggestion.event.event_id] = suggestion
        key = 'ww_more_' + gap.gap_id
        st.selectbox(f'More options ({len(choices)})', [None] + list(choices),
                      format_func=lambda event_id: _more_label(event_id, choices),
                      on_change=_selected_more, args=(key,), key=key)


def _export_block(event):
    """Offer a single-occurrence ICS download and the two provider compose links."""
    st.download_button('Download .ics', calendar_export.build_ics(event),
                        file_name=f'weekwise-{event.event_id}.ics', mime='text/calendar',
                        key=f'ww_export_{event.event_id}')
    st.link_button('Add to Google Calendar', calendar_export.google_calendar_link(event))
    st.link_button('Add to Outlook', calendar_export.outlook_calendar_link(event))
    _public_links(event)
    st.caption('Only this date is added – weekly courses are not added as a series.')


def _favorite_controls(connection, profile, event):
    """Save independent series, club and category favorites and refresh both dialog and grid."""
    targets = [('series', event.series_id, 'Favorite this course/series',
                event.series_id in profile.favorite_series_ids)]
    if event.club_id is not None:
        targets.append(('club', event.club_id, 'Favorite this club',
                        event.club_id in profile.favorite_club_ids))
    targets.append(('bundle', database.get_bundle_id(connection, event.bundle_key),
                    f'Favorite category "{event.bundle_name}"',
                    event.bundle_key in profile.favorite_bundle_keys))
    for kind, target_id, label, saved in targets:
        value = st.checkbox(label, value=saved, key=f'ww_favorite_{kind}_{event.event_id}')
        if value != saved:
            if value:
                database.add_favorite(connection, profile.user_id, kind, target_id)
            else:
                database.remove_favorite(connection, profile.user_id, kind, target_id)
            st.session_state['ww_open_event_id'] = event.event_id
            st.rerun()


def _interaction_action(connection, profile, event, action):
    """Save an action and reopen the dialog after a full rerun recomputes the week."""
    save_user_interaction(profile.user_id, event.event_id, action)
    st.session_state['ww_open_event_id'] = event.event_id
    st.rerun()


def _dialog_actions(connection, profile, event, now):
    """Offer confirmation, export and cancellation according to the stored occurrence state."""
    interaction = database.get_interaction(connection, profile.user_id, event.event_id)
    status = interaction['status'] if interaction else None
    if interaction and event.end < now and status != 'cancelled':
        render_feedback_widget(interaction, 'ww_detail_feedback', allow_edit=True, now=now)
        _public_links(event)
        return
    if status == 'confirmed':
        st.success('Confirmed')
        _export_block(event)
        if event.start > now:
            _invite_controls(connection, profile, event, now)
            if st.button('Cancel this event', key='ww_cancel_event'):
                _interaction_action(connection, profile, event, 'cancel')
    elif status == 'cancelled':
        st.info('Cancelled in WeekWise.')
        text = calendar_export.build_ics(event, cancel=True)
        st.download_button('Download cancellation .ics', text,
                            file_name=f'weekwise-{event.event_id}-cancel.ics', mime='text/calendar',
                            key=f'ww_cancel_export_{event.event_id}')
        st.caption(config.CALENDAR_CANCELLATION_HINT)
    if event.start > now and status in (None, 'cancelled'):
        if event.status in config.HIDDEN_STATUSES:
            st.info('This event is full or closed.')
        elif st.button('Confirm', type='primary', key='ww_confirm_event'):
            _interaction_action(connection, profile, event, 'confirm')
    if status != 'confirmed':
        _public_links(event)


def _invite_controls(connection, profile, event, now):
    """Invite selected friends to a confirmed future occurrence and show actual saved results."""
    st.subheader('Invite friends')
    frame = friends.get_friends_df(connection, profile.user_id)
    if frame.empty:
        st.caption('Add a friend on the Friends page to invite them.')
        return
    labels = {}
    for row in frame.reset_index().to_dict('records'):
        suffix = ' (demo)' if row['is_synthetic'] else ''
        labels[row['id']] = row['display_name'] + ' · ' + row['friend_code'] + suffix
    selected = st.multiselect('Choose friends', list(labels), format_func=labels.get,
                               key=f'ww_invite_friends_{event.event_id}')
    st.caption('Inviting shares this activity with the selected friends. '
               'Demo friends answer immediately with a labelled simulation.')
    if st.button('Send invitations', disabled=not selected,
                 key=f'ww_send_invites_{event.event_id}'):
        friends.send_invitations(connection, profile.user_id, event.event_id, selected, now)
        st.session_state['ww_open_event_id'] = event.event_id
        st.rerun()
    sent = friends.get_invitations(connection, profile.user_id)['sent']
    for row in sent.loc[sent['event_id'] == event.event_id].to_dict('records'):
        suffix = ' (simulated)' if row['is_simulated'] else ''
        st.caption(f'{row["recipient_name"]}: {row["status"]}{suffix}')


def calendar_fit_message(connection, event, now=None):
    """Assess an invited event against the active private calendar and other WeekWise plans."""
    now = config.local_now(now)
    if event.start <= now:
        return 'This event has already started.'
    start = datetime.combine(gaps.week_start(event.start), datetime.min.time())
    end = start + timedelta(days=config.DAYS_PER_WEEK)
    blocks, _, _, mode, message = load_current_calendar(
        connection, start, end, database.get_known_event_ids(connection))
    if mode == 'unavailable':
        return 'Calendar unavailable – fit could not be checked.'
    intervals = [(block.start, block.end) for block in blocks]
    confirmations = database.get_calendar_confirmations(connection, start, end).reset_index()
    for row in confirmations.to_dict('records'):
        if row['id'] != event.event_id:
            intervals.append((database.from_db_text(row['start_time']),
                              database.from_db_text(row['end_time'])))
    if gaps.placement_problem(event):
        return 'Outside your gaps – please check the time and location.'
    free = gaps.find_gaps_for_week(start.date(), intervals)
    fits = any(gap.fits(event) for gap in free)
    label = 'Fits your calendar' if fits else 'Overlaps with your calendar'
    if message:
        label += ' (fallback calendar)'
    return label


def render_invitation_response(connection, invitation, now=None, key_prefix='ww_received'):
    """Offer an atomic response and reopen accepted event details with the export block."""
    now = config.local_now(now)
    invitation_id = invitation['id']
    event_id = invitation['event_id']
    available = (database.from_db_text(invitation['start_time']) > now
                 and invitation['event_status'] not in config.HIDDEN_STATUSES)
    if invitation['status'] != 'pending':
        st.caption(invitation['status'].capitalize())
        return
    accept, decline = st.columns(2)
    if accept.button('Accept', disabled=not available, key=f'{key_prefix}_{invitation_id}_accept'):
        friends.respond_to_invitation(connection, invitation_id, True, now)
        st.session_state['ww_open_event_id'] = event_id
        st.rerun()
    if decline.button('Decline', key=f'{key_prefix}_{invitation_id}_decline'):
        friends.respond_to_invitation(connection, invitation_id, False, now)
        st.rerun()
    if not available:
        st.caption('This invitation can no longer be accepted; you can still decline it.')


def _dialog_social_details(connection, profile, event, now):
    """Show opted-in names and pending invitations for this one public event."""
    going = friends.get_friends_going_df(connection, profile.user_id, event.event_id)
    if not going.empty:
        st.text('Friends going: ' + ', '.join(going['display_name']))
    received = friends.get_invitations(connection, profile.user_id)['received']
    selected = received.loc[(received['event_id'] == event.event_id)
                            & (received['status'] == 'pending')]
    for row in selected.reset_index().to_dict('records'):
        st.badge(row['sender_name'] + ' invited you', color=config.INVITATION_BADGE_COLOR)
        st.caption(calendar_fit_message(connection, event, now))
        render_invitation_response(connection, row, now, key_prefix='ww_detail_invite')


# Course: L04 – Streamlit reruns dialog widgets as a fragment; writes request a full rerun.
@st.dialog('Event details', width='large')
def show_event_dialog(event_id):
    """Show one occurrence's complete details, state actions and independent favorite toggles."""
    connection = cached_connection()
    try:
        event = load_event(event_id)
        if event is None:
            st.error('This event is no longer available.')
            return
        profile = database.get_user_profile(connection, database.get_current_user_id(connection))
        st.subheader(event.title)
        direction_badge(event.direction_key)
        st.caption(event.bundle_name + ' · ' + event.source_label())
        st.write(f'{event.start:%a %d.%m.%Y %H:%M} – {event.end:%a %d.%m.%Y %H:%M}')
        st.text(f'{event.location} ({event.location_type})')
        st.caption('Price: ' + (event.price_label() or 'Not specified'))
        if event.display_tags():
            st.caption(' · '.join(event.display_tags()))
        if event.end_is_estimated:
            st.info(config.CALENDAR_ESTIMATED_END_NOTE)
        st.text(event.description)
        suggestion = score_current_events(connection, [event], profile)[0]
        st.caption(' · '.join([suggestion.match_label()] + suggestion.reasons))
        if gaps.placement_problem(event):
            st.warning('WeekWise did not check this against your calendar.')
        _dialog_social_details(connection, profile, event, config.local_now())
        _dialog_actions(connection, profile, event, config.local_now())
        _favorite_controls(connection, profile, event)
    except (OSError, ValueError, sqlite3.Error) as error:
        st.error(str(error) if isinstance(error, ValueError) else 'Could not load event details.')


def render_queued_dialog():
    """Open one feedback or details dialog after navigation and all page loops have finished."""
    if st.session_state.get('ww_feedback_open', False):
        show_feedback_dialog()
        return
    event_id = st.session_state.pop('ww_open_event_id', None)
    if event_id is not None:
        show_event_dialog(event_id)


def score_current_events(connection, events, profile, now=None, invited_by_map=None):
    """Score with the cached forest and current profile, history and opted-in friend counts."""
    scorer = cached_recommender(*database.get_rating_cache_key(connection))
    counts = friends.friends_going_counts(connection, profile.user_id,
                                         [event.event_id for event in events])
    averages = database.get_user_bundle_averages(connection, profile.user_id, now)
    if invited_by_map is None:
        invited_by_map = friends.pending_invitation_senders(connection, profile.user_id, now)
    return scorer.score_events(events, profile, counts, averages, invited_by_map)


def _save_feedback(interaction, action, rating, key_prefix, now):
    """Save feedback once, retain an open details dialog and refresh the model on full rerun."""
    save_user_interaction(interaction['user_id'], interaction['event_id'], action, rating, now)
    if key_prefix == 'ww_detail_feedback':
        st.session_state['ww_open_event_id'] = interaction['event_id']
    if action == 'rate':
        st.session_state['ww_rating_saved'] = True
    st.rerun()


def render_feedback_widget(interaction, key_prefix, allow_edit=False, now=None):
    """Render attendance and 0-based Streamlit stars, storing 1-based ratings after attendance."""
    now = config.local_now(now)
    key = f"{key_prefix}_{interaction['event_id']}"
    status, rating = interaction['status'], interaction['rating']
    # pandas represents mixed missing/integer ratings as NaN; SQLite returns None.
    if rating is not None and pd.isna(rating):
        rating = None
    if status == 'confirmed':
        st.text('Attended?')
        yes, no = st.columns(2)
        if yes.button('✓', type='primary', help='I attended', key=key + '_yes'):
            _save_feedback(interaction, 'attended', None, key_prefix, now)
        if no.button('✗', help='I did not attend', key=key + '_no'):
            _save_feedback(interaction, 'not_attended', None, key_prefix, now)
    elif status == 'not_attended':
        st.caption('Not attended')
    elif status == 'attended':
        if rating is not None:
            rating = int(rating)
            stars = '★' * rating + '☆' * (config.RATING_MAX - rating)
            st.caption(f'{stars} You rated {rating}/5')
        if rating is None or allow_edit:
            star_key = key + '_stars'
            if star_key not in st.session_state and rating is not None:
                st.session_state[star_key] = rating - 1
            value = st.feedback('stars', key=star_key)
            if value is not None and value + 1 != rating:
                _save_feedback(interaction, 'rate', value + 1, key_prefix, now)


def prepare_feedback_popup(connection, now=None):
    """Queue up to five oldest pending events once per session after onboarding completes."""
    user_id = database.get_current_user_id(connection)
    if user_id is None or st.session_state.get('ww_popup_done', False):
        return
    st.session_state['ww_popup_done'] = True
    pending = database.get_pending_feedback(connection, user_id, now)
    ids = list(pending['event_id'].head(config.FEEDBACK_POPUP_LIMIT))
    st.session_state['ww_feedback_ids'] = ids
    st.session_state['ww_feedback_open'] = bool(ids)


def _dismiss_feedback():
    """Keep unanswered rows for next session while suppressing this session's popup."""
    st.session_state['ww_feedback_open'] = False
    st.session_state['ww_popup_done'] = True


@st.dialog('How was it?', width='large', on_dismiss=_dismiss_feedback)
def show_feedback_dialog():
    """Collect attendance and stars for the original five events, allowing Done or Later."""
    connection = cached_connection()
    user_id = database.get_current_user_id(connection)
    try:
        for event_id in st.session_state.get('ww_feedback_ids', []):
            interaction = database.get_interaction(connection, user_id, event_id)
            row = database.get_event_row(connection, event_id)
            if interaction is not None and row is not None:
                with st.container(border=True):
                    st.write(row['title'])
                    st.caption(row['start_time'])
                    render_feedback_widget(interaction, 'ww_popup_feedback')
        done, later = st.columns(2)
        if done.button('Done', key='ww_feedback_done'):
            _dismiss_feedback()
            st.rerun()
        if later.button('Later', key='ww_feedback_later'):
            _dismiss_feedback()
            st.rerun()
    except (ValueError, sqlite3.Error) as error:
        st.error(str(error) if isinstance(error, ValueError) else 'Could not save feedback.')
